export const fetchUsers = async (): Promise<User[]> => {
  const response = await apiFetch('/users/');
  if (!response.ok) throw new Error(await errorDetail(response, 'Failed to fetch users'));
  return response.json();
};

/** Pre-provisions an email so its first sign-in lands with this role. */
export const createUser = async (email: string, role: Role): Promise<User> => {
  const response = await apiFetch('/users/', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, role }),
  });
  if (!response.ok) throw new Error(await errorDetail(response, 'Failed to add user'));
  return response.json();
};

export const updateUser = async (
  userId: number,
  patch: { role?: Role; is_active?: boolean },
): Promise<User> => {
  const response = await apiFetch(`/users/${userId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(patch),
  });
  if (!response.ok) throw new Error(await errorDetail(response, 'Failed to update user'));
  return response.json();
};
import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { fetchMe, logout } from '../services/api';
import type { MeResult } from '../services/api';
import { AuthContext } from '../hooks/useAuth';
import type { AuthState } from '../hooks/useAuth';
import { hasRole } from '../types/User';
import SignIn from '../pages/SignIn';

/** Gates the whole app on /api/auth/me: children render only when signed in. */
export default function AuthProvider({ children }: { children: ReactNode }) {
  const [me, setMe] = useState<MeResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMe()
      .then(setMe)
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
  }, []);

  const auth = useMemo<AuthState | null>(() => {
    if (me?.status !== 'signed_in') return null;
    return {
      user: me.user,
      can: (minRole) => hasRole(me.user, minRole),
      signOut: async () => {
        await logout();
        setMe({ status: 'signed_out' });
      },
    };
  }, [me]);

  if (error) return <SignIn error={error} />;
  if (me == null) return null;
  if (auth == null) return <SignIn disabled={me.status === 'disabled'} />;
  return <AuthContext.Provider value={auth}>{children}</AuthContext.Provider>;
}

